"""Build vanessa/cdmap.js + vanessa/cd/*.png: the official CFPB sample Closing Disclosure (form H-25(B), fixed-rate purchase,
public-domain federal model form, files.consumerfinance.gov/f/201403_cfpb_closing-disclosure_cover-H25B.pdf) rendered to
images, with a hotspot over every field placed from the PDF's own text coordinates, and a field-by-field explanation:
what it is · this sample's value · the rule · how to explain it to a borrower · what to check.

    python3 vanessa/scripts/build-cdmap.py <H-25B.pdf> <workdir>
"""
import json, re, subprocess, sys, html, pathlib, shutil
V = pathlib.Path(__file__).resolve().parent.parent
pdf, wd = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]); wd.mkdir(parents=True, exist_ok=True)
subprocess.run(["pdftoppm", "-f", "2", "-l", "6", "-r", "130", "-png", str(pdf), str(wd / "pg")], check=True)
subprocess.run(["pdftotext", "-bbox-layout", "-f", "2", "-l", "6", str(pdf), str(wd / "bbox.html")], check=True)
s = (wd / "bbox.html").read_text(encoding="utf-8")
pages = re.findall(r'<page width="([\d.]+)" height="([\d.]+)">(.*?)</page>', s, re.S)
W, H = float(pages[0][0]), float(pages[0][1])
L = []
for pi, (_, _, body) in enumerate(pages, 1):
    for m in re.finditer(r'<line xMin="([\d.]+)" yMin="([\d.]+)" xMax="([\d.]+)" yMax="([\d.]+)">(.*?)</line>', body, re.S):
        t = " ".join(html.unescape(x) for x in re.findall(r'>([^<]*)</word>', m.group(5)))
        L.append(dict(p=pi, x0=float(m.group(1)), y0=float(m.group(2)), x1=float(m.group(3)), y1=float(m.group(4)), t=t))

def find(p, rx, xmin=0, xmax=999, ymin=0):
    r = re.compile(rx)
    c = [l for l in L if l["p"] == p and r.search(l["t"]) and xmin <= l["x0"] <= xmax and l["y0"] >= ymin]
    if not c: raise SystemExit(f"anchor not found: p{p} {rx}")
    return sorted(c, key=lambda l: (l["y0"], l["x0"]))[0]

# F(id, page, anchor, box, title, value, what, rule, say, check, cat)
# box: ("row",x0,x1) same line band; ("to",x0,x1,next_anchor) band until next anchor; ("rows",x0,x1,n) n lines tall
F = []
def f(*a): F.append(a)
P1, P2, P3, P4, P5 = 1, 2, 3, 4, 5
LEFT, FULL, RIGHT = (36, 300), (36, 576), (312, 576)
