f("p2-h",P2,r"^H\. Other",("row",36,576),"H. Other","$2,400.00 (borrower)","Everything else: HOA fees, inspections, warranty, commissions, owner's title.","No tolerance limit (not required by the lender).","\"These aren't loan costs — they're other costs of the purchase, like the HOA and the owner's title policy.\"","Each item per the contract and HOA demand.","H")
f("p2-h1",P2,r"^01 HOA Capital Contribution",("row",36,576),"H.01 HOA Capital Contribution","$500.00","One-time HOA transfer/capital fee.","","\"A one-time fee the HOA charges new owners.\"","Per HOA demand.","H")
f("p2-h2",P2,r"^02 HOA Processing Fee",("row",36,576),"H.02 HOA Processing Fee","$150.00","HOA transfer/document processing.","","\"The HOA's fee to transfer the account to you.\"","","H")
f("p2-h3",P2,r"^03 Home Inspection Fee",("row",36,576),"H.03 Home Inspection Fee","$750 (borrower) · $750 (seller)","General home inspection.","","\"Your home inspection.\"","","H")
f("p2-h4",P2,r"^04 Home Warranty Fee",("row",36,576),"H.04 Home Warranty Fee","$450 (seller-paid)","One-year home warranty.","","\"A home warranty for the first year — paid by the seller here.\"","","H")
f("p2-h5",P2,r"^05 Real Estate Commission",("row",36,576),"H.05–06 Real Estate Commissions","$5,700 + $5,700 (seller-paid)","Listing and buyer-agent commissions.","Commissions are negotiable. After the 2024 NAR settlement, buyer-agent compensation is set in a written buyer agreement.","\"These are the agents' commissions, paid by the seller in this sale.\"","Per listing and buyer-broker agreements.","H")
f("p2-h7",P2,r"^07 Title – Owner",("row",36,576),"H.07 Title – Owner's Title Insurance (optional)","$1,000.00","Protects the BUYER's ownership against title defects. Marked optional because the lender doesn't require it.","Shown as owner's premium + simultaneous lender's premium − full lender's premium (§1026.37(g)(4)) — so this number can look different from the title company's rate card.","\"This policy protects YOU if someone ever claims an ownership problem from before you bought. It's 'optional' only because the lender doesn't require it — I strongly recommend it. In much of Southern California the seller customarily pays it — check your contract.\"","Who pays per contract/county custom.","H")
f("p2-i",P2,r"^I\. TOTAL OTHER COSTS",("rows",36,576,2),"I. Total Other Costs","$5,018.05","E + F + G + H, borrower-paid.","","\"The non-loan costs add up to $5,018.05.\"","= E + F + G + H.","I")
f("p2-j",P2,r"^J\. TOTAL CLOSING COSTS",("rows",36,576,2),"J. Total Closing Costs","$9,712.10 ($9,682.30 at closing + $29.80 before)","D + I − Lender Credits. Carries to page 1 and page 3.","","\"Total closing costs: $9,712.10, of which $29.80 you already paid for the credit report.\"","= D + I − credits.","J")
f("p2-lc",P2,r"^Lender Credits",("row",36,576),"Lender Credits","$0","Money from the lender toward closing costs (usually from choosing a slightly higher rate).","The lender credit can't DECREASE from the LE without a valid changed circumstance (zero tolerance). Tolerance cures appear as a credit here: 'includes $X credit for increase in closing costs above legal limit'.","\"No lender credit on this loan. If there were one, it would reduce your closing costs here.\"","Equal to or larger than the LE's lender credit.","J")
# ---------------- PAGE 3 ----------------
f("p3-ctc",P3,r"^Calculating Cash to Close",("rows",36,576,2),"Calculating Cash to Close","LE $16,054.00 → Final $14,147.26","Compares each piece of cash to close from the Loan Estimate to the final, with 'Did this change?' and the reason.","Any YES must say why and where to look.","\"This table explains why your cash to close is different from the Loan Estimate.\"","Every YES has an explanation you can read to the borrower.","p3")
f("p3-tcc",P3,r"^Total Closing Costs \(J\)",("row",36,576),"Total Closing Costs (J)","$8,054.00 → $9,712.10 · YES","Change in total closing costs. The table says whether it exceeded the legal limits and by how much.","If the increase is over tolerance, the CD shows the cure amount.","\"Your closing costs went up from the estimate, mostly because of items in Sections F and G that are based on actual dates and premiums. None of the fees with limits went over those limits.\"","Look for 'Increase exceeds legal limits by $X' — that's a cure owed.","p3")
f("p3-pbc",P3,r"^Closing Costs Paid Before Closing",("row",36,576),"Closing Costs Paid Before Closing","$0 → −$29.80 · YES","Costs already paid (credit report), subtracted from cash to close.","","\"You already paid $29.80 for the credit report, so it comes off what you bring.\"","","p3")
f("p3-fin",P3,r"^Closing Costs Financed",("rows",36,576,2),"Closing Costs Financed","$0","Closing costs rolled into the loan amount (common on refinances).","","\"None of your costs were added to the loan.\"","Refi: should equal loan amount − payoffs when costs are financed.","p3")
f("p3-dp",P3,r"^Down Payment/Funds from Borrower",("row",36,576),"Down Payment / Funds from Borrower","$18,000 → $18,000 · NO","Price minus loan amount.","","\"Your down payment is $18,000 — 10%.\"","","p3")
f("p3-dep",P3,r"^Deposit$",("row",36,576),"Deposit","−$10,000","Earnest money already given to escrow — a credit toward cash to close.","","\"Your $10,000 good-faith deposit is already at escrow and counts toward what you owe.\"","EMD receipt in file.","p3")
f("p3-ffb",P3,r"^Funds for Borrower",("row",36,576),"Funds for Borrower","$0","Cash back to the borrower from the loan (e.g., cash-out refi).","","\"You're not receiving any loan funds back.\"","","p3")
f("p3-sc",P3,r"^Seller Credits",("row",36,576),"Seller Credits","$0 → −$2,500 · YES","Seller-paid credit toward the buyer's costs.","Must stay within program concession limits (conventional 3–9% by LTV; FHA 6%; VA 4% + normal costs) and can't exceed actual costs.","\"The seller is giving you a $2,500 credit, which reduces what you bring.\"","Matches the contract addendum; within the program's limit.","p3")
f("p3-adj",P3,r"^Adjustments and Other Credits",("row",36,576),"Adjustments and Other Credits","$0 → −$1,035.04 · YES","Prorations and other credits (taxes, HOA, title rebate).","Details on the summary: −$750 title rebate − $365.04 unpaid city taxes + $80 HOA paid ahead = −$1,035.04.","\"These are fair-share adjustments: the seller owes you for taxes up to closing, you reimburse the seller for HOA dues they prepaid, and the title company gave a $750 rebate.\"","Math adds up to the summary sections.","p3")
f("p3-total",P3,r"^Cash to Close$",("row",36,576),"Cash to Close (final)","$14,147.26","The bottom line — what to bring.","","\"So the final amount to bring is $14,147.26.\"","Same as page 1 and the K − L calculation.","p3")
f("p3-k",P3,r"^K\. Due from Borrower at Closing",("to",36,310,r"^L\. Paid Already"),"K. Due from Borrower at Closing","$189,762.30","Everything the borrower owes: price + closing costs (J) + adjustments for items the seller paid in advance (e.g., HOA dues already paid for the rest of the month).","","\"This is everything you owe: the price, your closing costs and a small HOA reimbursement.\"","$180,000 + $9,682.30 + $80 = $189,762.30.","p3")
f("p3-l",P3,r"^L\. Paid Already by or on Behalf",("to",36,310,r"^CALCULATION$"),"L. Paid Already by or on Behalf of Borrower","$175,615.04","Everything already paid or credited: deposit, the new loan, seller credit, other credits, unpaid seller taxes.","","\"This is what's already covered — your deposit, the loan, the seller credit, the title rebate and the seller's share of taxes.\"","$10,000 + $162,000 + $2,500 + $750 + $365.04 = $175,615.04.","p3")
f("p3-calc",P3,r"^Total Due from Borrower at Closing \(K\)",("rows",36,310,3),"Calculation — Cash to Close","$189,762.30 − $175,615.04 = $14,147.26 From Borrower","K minus L. 'From' means the borrower brings money; 'To' means the borrower receives money.","","\"K minus L is the $14,147.26 you bring.\"","","p3")
f("p3-m",P3,r"^M\. Due to Seller at Closing",("to",312,576,r"^N\. Due from Seller"),"M. Due to Seller at Closing (seller's side)","Sale price + prorations owed to seller","The seller's side of the ledger. Lenders may omit the seller columns on the buyer's CD (a separate seller CD is used).","","\"This side shows the seller's numbers — you don't need to worry about it.\"","","p3")
f("p3-n",P3,r"^N\. Due from Seller at Closing",("to",312,576,r"^CALCULATION$"),"N. Due from Seller at Closing","Payoffs, seller-paid costs, credits","Seller's payoffs and costs.","","\"These are the seller's payoffs and costs.\"","","p3")
# ---------------- PAGE 4 ----------------
f("p4-assume",P4,r"^Assumption$",("to",36,300,r"^Demand Feature$"),"Assumption","Will not allow assumption","Whether a future buyer can take over this loan on its terms.","Conventional loans are generally not assumable; FHA and VA loans are assumable with lender approval (a real selling point when rates rise).","\"If you sell, the buyer can't take over this loan — it gets paid off.\" (FHA/VA: \"A qualified buyer may be able to take over your low rate — that can help you sell later.\")","FHA/VA should show 'will allow, under certain conditions'.","p4")
f("p4-demand",P4,r"^Demand Feature$",("to",36,300,r"^Late Payment$"),"Demand Feature","Does not have one","Whether the lender can demand full repayment early for reasons other than default.","","\"The lender can't call the loan due early as long as you keep your agreement.\"","Should be 'does not have'.","p4")
f("p4-late",P4,r"^Late Payment$",("to",36,300,r"^Negative Amortization"),"Late Payment","More than 15 days late → 5% of P&I","The late-charge terms from the note.","FHA and VA notes use 4% after 15 days; conventional is commonly 5%.","\"Payments are due on the 1st. If one is more than 15 days late, there's a late fee of 5% of principal and interest — about $38. Set up autopay.\"","Matches the note.","p4")
f("p4-negam",P4,r"^Negative Amortization",("to",36,300,r"^Partial Payments$"),"Negative Amortization","Does not have","Whether the balance can grow because payments don't cover interest.","Not allowed on qualified mortgages.","\"Your balance only goes down — never up.\"","Should be 'do not have'.","p4")
f("p4-partial",P4,r"^Partial Payments$",("to",36,300,r"^Security Interest$"),"Partial Payments","May accept and apply","How the lender handles less than a full payment.","Policy can change if the loan is sold.","\"If you ever send less than a full payment, this tells you what the lender does with it. Always call the servicer first if you're having trouble.\"","","p4")
f("p4-security",P4,r"^Security Interest$",("to",36,300,r"^CLOSING DISCLOSURE$"),"Security Interest","456 Somewhere Ave.","The property is collateral; the lender can foreclose if the loan isn't paid.","","\"The home secures the loan, so it's important to keep payments, taxes and insurance current.\"","","p4")
f("p4-escrow",P4,r"^Escrow Account$",("to",312,576,r"^Escrowed$"),"Escrow Account","Will have an escrow (impound) account","Whether the servicer collects and pays taxes and insurance.","Required for higher-priced mortgages (first 5 years), FHA, VA, USDA; conventional ≥ 80% LTV often requires it; CA may allow waivers with a fee/price adjustment.","\"You'll have an impound account. Each month part of your payment goes into it, and the servicer pays your taxes and insurance for you.\"","Waiver requested? Shows the no-escrow box and any waiver fee.","p4")
f("p4-esc1",P4,r"^Escrowed$",("rows",312,576,3),"Escrowed Property Costs over Year 1","$2,473.56","Total escrowed costs for the first year (taxes + insurance).","= monthly escrow × 12 ($206.13 × 12).","\"About $2,474 a year for taxes and insurance is collected through your payment.\"","","p4")
f("p4-esc2",P4,r"^Non-Escrowed$",("rows",312,576,3),"Non-Escrowed Property Costs over Year 1","$1,800.00 (HOA dues)","Costs the borrower pays directly.","","\"You'll pay $1,800 a year in HOA dues directly to the association.\"","Mello-Roos / HOA / supplemental tax — anything not in escrow.","p4")
f("p4-esc3",P4,r"^Initial Escrow$",("rows",312,576,2),"Initial Escrow Payment","$412.25","Cushion deposited at closing = page 2 Section G.","","\"This is the escrow cushion you paid at closing.\"","= Section G.","p4")
f("p4-esc4",P4,r"^Monthly Escrow$",("rows",312,576,2),"Monthly Escrow Payment","$206.13","Escrow portion of each monthly payment = page 1.","","\"$206.13 of each payment goes to escrow.\"","","p4")
f("p4-noesc",P4,r"^No Escrow$",("to",312,576,r"^In the future,"),"No Escrow (and Escrow Waiver Fee)","Not checked","Used when there's no escrow account — the borrower pays taxes and insurance directly; any waiver fee shows here.","","\"If you'd chosen no impound account, you'd pay taxes and insurance yourself, usually in big lump sums.\"","","p4")
f("p4-future",P4,r"^In the future,",("to",312,576,r"^PAGE 4 OF 5"),"In the Future","Escrow can change; consequences of not paying","Escrow payments change with taxes/insurance; if property costs go unpaid the lender can add them to the loan, add escrow, or force-place insurance.","","\"Your escrow is reviewed every year. If taxes or insurance go up, your payment goes up. Never let insurance lapse — lender-placed insurance costs much more.\"","","p4")
# ---------------- PAGE 5 ----------------
f("p5-top",P5,r"^Total of Payments",("rows",36,300,3),"Total of Payments","$285,803.36","Everything paid over the life of the loan if payments are made as scheduled: principal, interest, mortgage insurance and loan costs (Section D).","Considered accurate if it's not understated by more than $100 (or overstated). If inaccurate it may need a corrected CD.","\"If you keep this loan all 30 years and pay as scheduled, you'll pay about $285,803 in total. Most people sell or refinance well before then.\"","","p5")
f("p5-fc",P5,r"^Finance Charge\.",("rows",36,300,2),"Finance Charge","$118,830.27","The dollar cost of credit: interest + MI + prepaid finance charges (points, most lender fees, prepaid interest).","Tolerance: accurate if understated by no more than $100 (§1026.18(d)). Used to compute the APR.","\"This is what the loan costs you over its life in dollars — mostly interest.\"","","p5")
f("p5-af",P5,r"^Amount Financed",("rows",36,300,2),"Amount Financed","$162,000.00","Loan amount minus prepaid finance charges — the base for the APR.","","\"This is the amount the APR is calculated on.\"","","p5")
f("p5-apr",P5,r"^Annual Percentage Rate",("rows",36,300,3),"APR","4.174%","The yearly cost of the loan including fees — higher than the note rate because it includes points, fees and MI.","If the APR becomes inaccurate (increases more than 1/8% on a regular loan, 1/4% irregular) a NEW 3-business-day waiting period is required.","\"Your interest rate is 3.875%. The APR of 4.174% adds in your fees and mortgage insurance so you can compare loans apples to apples.\"","Compare to LE APR; jump > 0.125% → new 3-day wait.","p5")
f("p5-tip",P5,r"^Total Interest Percentage",("rows",36,300,3),"Total Interest Percentage (TIP)","69.46%","Total interest over the life of the loan as a percentage of the loan amount.","","\"Over 30 years you'd pay interest equal to about 69% of what you borrowed.\"","","p5")
f("p5-apprl",P5,r"^Appraisal$",("to",312,576,r"^Contract Details$"),"Appraisal","Copy required 3 days before closing","Right to a free copy of the appraisal.","ECOA/Reg B §1002.14: copy promptly and at least 3 business days before consummation (waivable).","\"You'll get a copy of the appraisal at no cost at least three days before closing.\"","Delivery documented.","p5")
f("p5-contract",P5,r"^Contract Details$",("to",312,576,r"^Liability after Foreclosure$"),"Contract Details","See note and deed of trust","Points the borrower to the note/security instrument for default, acceleration and prepayment terms.","","\"The note and deed of trust you sign have the full legal details.\"","","p5")
f("p5-liab",P5,r"^Liability after Foreclosure$",("to",312,576,r"^Refinance$"),"Liability after Foreclosure","State law may protect you","Whether the borrower can owe a deficiency after a foreclosure.","California anti-deficiency law (CCP §580b) generally protects purchase-money loans on owner-occupied 1–4 units; a refinance or additional debt can change that protection. Not legal advice.","\"In California, a purchase loan on your own home generally can't come after you for a shortfall after foreclosure — but refinancing later can change that. For specifics, talk to an attorney.\"","CA purchase: 'state law may protect you' box checked.","p5")
f("p5-refi",P5,r"^Refinance$",("to",312,576,r"^Tax Deductions$"),"Refinance","Not guaranteed","No promise that a future refinance will be available.","Never promise a future refinance to sell a loan.","\"You might be able to refinance later if rates drop, but that depends on your finances, the home's value and the market — it isn't guaranteed.\"","","p5")
f("p5-tax",P5,r"^Tax Deductions$",("rows",312,576,4),"Tax Deductions","","Interest on debt above fair market value isn't deductible.","Refer tax questions to a tax advisor.","\"For tax questions, check with your tax advisor.\"","","p5")
f("p5-q",P5,r"^Questions\? If you have questions",("rows",95,300,6),"Questions?","CFPB contact","Where to get help or file a complaint.","","\"If anything is unclear, call me first — and you can always contact the Consumer Financial Protection Bureau.\"","","p5")
f("p5-contact",P5,r"^Contact Information$",("to",36,576,r"^Confirm Receipt$"),"Contact Information","Lender · Mortgage Broker · Agents · Settlement Agent","Names, addresses, NMLS and state license IDs and the contact person for each party.","Mortgage broker and loan officer NMLS IDs are required. For our loans: Patriot Pacific Financial Corp NMLS 1921615 · Steven Shearrill NMLS 2449246 · CA DRE 01988316.","\"Here's everyone involved and how to reach them. I'm listed as your loan officer with my NMLS and license numbers.\"","Broker column filled in with our NMLS/DRE IDs.","p5")
f("p5-sign",P5,r"^Confirm Receipt$",("rows",36,576,6),"Confirm Receipt","Applicant signature","Signature acknowledges RECEIPT only.","Signing does not mean the borrower accepts the loan or must close.","\"Signing here only says you received this form — it doesn't commit you to the loan.\"","Signed/e-signed receipt date ≥ 3 business days before closing.","p5")

# ---------------- build ----------------
fields = []
for (fid, p, rx, box, title, val, what, rule, say, check, cat) in F:
    a = find(p, rx)
    if box[0] == "row":
        x0, x1 = box[1], box[2]; y0, y1 = a["y0"] - 1.5, a["y1"] + 1.5
    elif box[0] == "rows":
        x0, x1, n = box[1], box[2], box[3]; y0 = a["y0"] - 1.5; y1 = a["y1"] + 1.5 + (n - 1) * 10.4
    else:
        x0, x1, nxt = box[1], box[2], box[3]
        b = find(p, nxt, ymin=a["y0"] + 1, xmin=x0 - 8, xmax=x1)
        y0, y1 = a["y0"] - 1.5, b["y0"] - 2
    fields.append(dict(id=fid, p=p, cat=cat, b=[round(x0 / W * 100, 2), round(y0 / H * 100, 2), round((x1 - x0) / W * 100, 2), round((y1 - y0) / H * 100, 2)],
                       t=title, v=val, what=what, rule=rule, say=say, check=check))
cd = V / "cd"; cd.mkdir(exist_ok=True)
imgs = []
for i in range(1, 6):
    src = wd / f"pg-{i + 1}.png"
    shutil.copy(src, cd / f"cd-p{i}.png"); imgs.append(f"cd/cd-p{i}.png")
data = dict(src="https://files.consumerfinance.gov/f/201403_cfpb_closing-disclosure_cover-H25B.pdf", form="H-25(B) Closing Disclosure — Fixed Rate Loan Sample (CFPB, public domain)", pages=imgs, aspect=round(H / W, 4), fields=fields)
(V / "cdmap.js").write_text("// Field map for the CFPB sample Closing Disclosure (H-25(B)). Generated by scripts/build-cdmap.py — edit the script, not this file.\nwindow.CD_MAP=" + json.dumps(data, ensure_ascii=False, separators=(",", ":")) + ";\n", encoding="utf-8")
print(len(fields), "fields ·", ", ".join(f"p{i}:{sum(1 for x in fields if x['p']==i)}" for i in range(1, 6)))
